llm_calls.content:
{
  "task_summary": "Predict an individual's income-to-poverty ratio category from ACS demographic, education, employment, and household variables.",
  "ranking": [
    {
      "rank": 1,
      "feature": "ESR",
      "rationale": "Employment status is directly and stably related to income and poverty risk."
    },
    {
      "rank": 2,
      "feature": "WKHP",
      "rationale": "Usual weekly work hours strongly reflect labor supply and earnings capacity."
    },
    {
      "rank": 3,
      "feature": "OCCP",
      "rationale": "Occupation captures durable differences in wages and economic status across states."
    },
    {
      "rank": 4,
      "feature": "SCHL",
      "rationale": "Educational attainment is a broadly transferable predictor of earnings and poverty."
    },
    {
      "rank": 5,
      "feature": "AGEP",
      "rationale": "Age captures life-cycle labor-market participation and income patterns."
    },
    {
      "rank": 6,
      "feature": "DIS",
      "rationale": "Overall disability status can affect employment, hours, and income stability."
    },
    {
      "rank": 7,
      "feature": "MAR",
      "rationale": "Marital status relates to household resources and poverty thresholds in a fairly stable way."
    },
    {
      "rank": 8,
      "feature": "DREM",
      "rationale": "Cognitive difficulty can materially affect work capacity and economic outcomes."
    },
    {
      "rank": 9,
      "feature": "MIL",
      "rationale": "Military service can indicate work history, benefits, and income support."
    },
    {
      "rank": 10,
      "feature": "RELP",
      "rationale": "Household relationship helps infer dependency and resource-sharing, but may encode household-composition shortcuts."
    },
    {
      "rank": 11,
      "feature": "DEAR",
      "rationale": "Hearing difficulty may affect employment but is less directly predictive than broad disability or cognition."
    },
    {
      "rank": 12,
      "feature": "DEYE",
      "rationale": "Vision difficulty can affect work opportunities, though its income signal is usually weaker."
    },
    {
      "rank": 13,
      "feature": "ESP",
      "rationale": "Parental employment is important for children but less generally applicable across all individuals."
    },
    {
      "rank": 14,
      "feature": "GCL",
      "rationale": "Grandparents living with grandchildren may indicate household economic structure but is narrow and context-dependent."
    },
    {
      "rank": 15,
      "feature": "SEX",
      "rationale": "Sex is correlated with income through labor-market disparities but is a demographic shortcut to penalize."
    },
    {
      "rank": 16,
      "feature": "CIT",
      "rationale": "Citizenship may correlate with labor access and benefits but risks encoding immigration and state-specific composition."
    },
    {
      "rank": 17,
      "feature": "NATIVITY",
      "rationale": "Nativity is an indirect demographic marker with weaker causal connection and potential distribution shift."
    },
    {
      "rank": 18,
      "feature": "MIG",
      "rationale": "Migration status can proxy local economic conditions and geography-specific artifacts."
    },
    {
      "rank": 19,
      "feature": "ANC",
      "rationale": "Ancestry is mostly a demographic proxy and likely brittle across states."
    },
    {
      "rank": 20,
      "feature": "RAC1P",
      "rationale": "Race is highly sensitive and may encode demographic or geographic shortcuts rather than transferable mechanisms."
    }
  ]
}
